@@ -830,16 +830,20 @@ bool ai7ThumbnailSize(size_t width, size_t height, size_t& rgbSize) {
   if (width == 0 || height == 0)
     return false;

-  constexpr size_t bytesPerPixel = 3;
+  const auto w = static_cast<uint32_t>(width);
+  const auto h = static_cast<uint32_t>(height);
+  if (w == 0 || h == 0)
+    return false;

-  if (width > std::numeric_limits<size_t>::max() / height)
+  constexpr uint32_t bytesPerPixel = 3;
