     return false;

-  const size_t pixels = width * height;
-  if (pixels > std::numeric_limits<size_t>::max() / bytesPerPixel)
+  const uint32_t pixels = w * h;
+  if (pixels > std::numeric_limits<uint32_t>::max() / bytesPerPixel)
     return false;

-  rgbSize = pixels * bytesPerPixel;
+  rgbSize = static_cast<size_t>(pixels) * bytesPerPixel;
   return rgbSize <= maxAi7ThumbnailSize;
 }

